CREATE OR REPLACE FUNCTION private.employee_text(p_value text, p_limit integer, p_required boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE value text:=nullif(private.employee_trim(p_value),'');
BEGIN
 IF (p_required AND value IS NULL) OR char_length(value)>p_limit THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 RETURN value;
END;
$function$

private.employee_operation_impl_v1(uuid,.definition:
CREATE OR REPLACE FUNCTION private.employee_operation_impl_v1(p_operation_id uuid, p_resolution text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor uuid; op private.employee_operations%ROWTYPE;
BEGIN
 actor:=private.employee_lock_actor();
 IF p_operation_id IS NULL OR p_resolution IS NULL OR p_resolution NOT IN('read','abandon') THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 PERFORM private.employee_lock_operation(actor,p_operation_id);
 SELECT * INTO op FROM private.employee_operations WHERE actor_id=actor AND operation_id=p_operation_id;
 IF NOT FOUND AND p_resolution='abandon' THEN
  INSERT INTO private.employee_operations(actor_id,operation_id,state) VALUES(actor,p_operation_id,'abandoned') RETURNING * INTO op;
 END IF;
 RETURN jsonb_build_object('state',coalesce(op.state,'absent'),'result',op.result);
END;
$function$

private.employee_reporting_request(uuid,.definition:
CREATE OR REPLACE FUNCTION private.employee_reporting_request(p_employee_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE item jsonb; manager uuid; raw text; from_day date; until_day date; intervals jsonb:='[]';
BEGIN
 IF jsonb_typeof(p_payload->'mode') IS DISTINCT FROM 'string' OR p_payload->>'mode' NOT IN('schedule','correction')
  OR jsonb_typeof(p_payload->'intervals') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_payload->'intervals') LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
  IF NOT item?&ARRAY['managerEmployeeId','from','until'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(item) k WHERE k NOT IN('managerEmployeeId','from','until'))
   OR jsonb_typeof(item->'managerEmployeeId') NOT IN('string','null') THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
  raw:=item->>'managerEmployeeId'; manager:=NULL;
  IF raw IS NOT NULL THEN
   IF raw!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
   manager:=raw::uuid;
  END IF;
  IF manager=p_employee_id THEN RAISE EXCEPTION 'REPORTING_SELF_REFERENCE' USING ERRCODE='22023'; END IF;
  from_day:=private.employee_date(item->'from'); until_day:=private.employee_date(item->'until');
  IF from_day IS NULL OR until_day<=from_day THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
  intervals:=intervals||jsonb_build_array(jsonb_build_object('managerEmployeeId',manager,'from',to_char(from_day,'YYYY-MM-DD'),'until',to_char(until_day,'YYYY-MM-DD')));
 END LOOP;
 -- Compare each start with the maximum previous end, including an unbounded end.
 IF EXISTS(SELECT 1 FROM (SELECT (value->>'from')::date start_day,
    max(coalesce((value->>'until')::date,'infinity'::date)) OVER(ORDER BY (value->>'from')::date,(value->>'until')::date ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) prior_end
   FROM jsonb_array_elements(intervals)) ordered WHERE start_day<prior_end) THEN
  RAISE EXCEPTION 'REPORTING_OVERLAP' USING ERRCODE='22023';
 END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'from'),'[]') INTO intervals FROM jsonb_array_elements(intervals);
 RETURN jsonb_build_object('mode',p_payload->>'mode','intervals',intervals);
END;
$function$

private.employee_audit_impl_v1(uuid,inte.definition:
CREATE OR REPLACE FUNCTION private.employee_audit_impl_v1(p_employee_id uuid, p_page integer, p_page_size integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result_rows jsonb; row_total bigint;
BEGIN
 PERFORM private.employee_require_director(); PERFORM private.employee_read_guard('',p_page,p_page_size);
 IF p_employee_id IS NULL THEN RAISE EXCEPTION 'Employee id required' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM private.employee_records WHERE id=p_employee_id) THEN RAISE EXCEPTION 'Employee not found' USING ERRCODE='P0002'; END IF;
 SELECT count(*) INTO row_total FROM private.employee_audit_events WHERE employee_id=p_employee_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'employeeId',a.employee_id,'actorId',a.actor_id,'actorName',a.actor_name,
  'recordedAt',to_char(a.recorded_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'effectiveDate',a.effective_date,
  'action',a.action,'reason',a.reason,'sourceReference',a.source_reference,
  'before',private.employee_audit_projection(a.before_data),'after',private.employee_audit_projection(a.after_data))
  ORDER BY a.recorded_at DESC,a.id DESC),'[]') INTO result_rows FROM
  (SELECT * FROM private.employee_audit_events WHERE employee_id=p_employee_id ORDER BY recorded_at DESC,id DESC
   LIMIT p_page_size OFFSET (p_page::bigint-1)*p_page_size) a;
 RETURN jsonb_build_object('rows',result_rows,'total',row_total,'page',p_page,'pageSize',p_page_size);
END;
$function$

private.employee_reporting_apply(uuid,js.definition:
CREATE OR REPLACE FUNCTION private.employee_reporting_apply(p_employee_id uuid, p_payload jsonb, p_actor uuid, p_source text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE new_revision bigint;
BEGIN
 UPDATE private.employee_records SET reporting_revision=reporting_revision+1 WHERE id=p_employee_id RETURNING reporting_revision INTO new_revision;
 INSERT INTO private.employee_reporting_revisions(employee_id,revision,mode,actor_id,source_reference)
  VALUES(p_employee_id,new_revision,p_payload->>'mode',p_actor,p_source);
 INSERT INTO private.employee_reporting_intervals(employee_id,revision,ordinal,manager_employee_id,from_date,until_date)
  SELECT p_employee_id,new_revision,(ordinality-1)::integer,(value->>'managerEmployeeId')::uuid,(value->>'from')::date,(value->>'until')::date
   FROM jsonb_array_elements(p_payload->'intervals') WITH ORDINALITY;
 UPDATE private.employee_reporting_guard SET revision=revision+1 WHERE singleton;
END;
$function$

private.employee_page_impl_v1(text,text,.definition:
CREATE OR REPLACE FUNCTION private.employee_page_impl_v1(p_query text, p_status text, p_page integer, p_page_size integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE q text; result_rows jsonb; row_total bigint;
BEGIN
 PERFORM private.employee_require_director();
 q:=private.employee_read_guard(p_query,p_page,p_page_size);
 IF p_status IS NOT NULL AND p_status NOT IN('draft','active','ended') THEN RAISE EXCEPTION 'Invalid employee status' USING ERRCODE='22023'; END IF;
 WITH matches AS MATERIALIZED (SELECT e.* FROM private.employee_records e WHERE (p_status IS NULL OR e.recorded_status=p_status)
  AND (q='' OR strpos(lower(e.name),lower(q))>0 OR strpos(lower(coalesce(e.employee_number,'')),lower(q))>0)),
 page_rows AS (SELECT * FROM matches ORDER BY name COLLATE "C",id LIMIT p_page_size OFFSET (p_page::bigint-1)*p_page_size)
 SELECT (SELECT count(*) FROM matches),coalesce(jsonb_agg(jsonb_build_object('id',r.id,'version',r.version)||private.employee_fields(r::private.employee_records)
  ORDER BY r.name COLLATE "C",r.id),'[]') INTO row_total,result_rows FROM page_rows r;
 RETURN jsonb_build_object('rows',result_rows,'total',row_total,'page',p_page,'pageSize',p_page_size);
END;
$function$

